import {ARCHIVE_PACK,ARCHIVE_PAGES,ARCHIVE_TASKS,ARCHIVE_DETAILS,ARCHIVE_TEXT_LIMIT,ARCHIVE_SOURCES,ARCHIVE_EVENTS,ARCHIVE_SITES,ARCHIVE_MAP_CARDS,ARCHIVE_QUESTIONS,ARCHIVE_REPLY_FIELDS,archiveSourceById,archiveEventById,archiveQuestionById,archiveMapCardById,archiveReplyFieldById} from './travelers-archive-content.mjs';
const SUPPORT=['help','example','audio','together'],READING=['unobserved','together','reported-independent'];
const TASK_IDS=['global','map-photo','map-gauge','order','reply',...ARCHIVE_QUESTIONS.map(q=>q.id)];
const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const clone=x=>JSON.parse(JSON.stringify(x));
const keys=(x,required,optional=[])=>object(x)&&required.every(k=>Object.hasOwn(x,k))&&Object.keys(x).every(k=>required.includes(k)||optional.includes(k));
const unique=(x,list,max=list.length)=>Array.isArray(x)&&x.length<=max&&new Set(x).size===x.length&&x.every(v=>list.includes(v));
const equal=(a,b)=>a===b||(Array.isArray(a)&&Array.isArray(b)&&a.length===b.length&&a.every((v,i)=>equal(v,b[i])))||(object(a)&&object(b)&&Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>Object.hasOwn(b,k)&&equal(a[k],b[k])));
const supportValid=x=>object(x)&&Object.entries(x).every(([k,v])=>SUPPORT.includes(k)&&v===true);
const supportsValid=x=>object(x)&&Object.entries(x).every(([id,s])=>TASK_IDS.includes(id)&&supportValid(s));
const sourceIds=ARCHIVE_SOURCES.map(s=>s.id),eventIds=ARCHIVE_EVENTS.map(e=>e.id);
const textValid=x=>typeof x==='string'&&Array.from(x).length<=ARCHIVE_TEXT_LIMIT;
const choiceValid=(field,value)=>value===null||archiveReplyFieldById(field)?.choices.some(c=>c.id===value)===true;
const replyValid=r=>keys(r,['claim','evidence','limit','text'])&&ARCHIVE_REPLY_FIELDS.every(f=>choiceValid(f.id,r[f.id]))&&textValid(r.text);
const siteValid=x=>x===null||ARCHIVE_SITES.some(s=>s.id===x);
const mapValid=x=>keys(x,['photo','gauge'])&&siteValid(x.photo)&&siteValid(x.gauge);
const answersValid=x=>object(x)&&Object.entries(x).every(([id,a])=>archiveQuestionById(id)?.choices.some(c=>c.id===a));
const sourceSnapshots=ids=>ids.map(id=>clone(archiveSourceById(id)));
function questionResult(id,choice){const q=archiveQuestionById(id);if(!q||!q.choices.some(c=>c.id===choice))return null;return {correct:choice===q.answer,feedback:`${choice==='unsure'?'We can look together. ':''}${q.feedback}`};}
function mapResult(cardId,siteId){const c=archiveMapCardById(cardId);if(!c||!siteValid(siteId))return null;return {correct:siteId===c.answer,feedback:siteId===null?'No place chosen yet. Compare the source’s place name with the map legend.':`${siteId===c.answer?'The labels match. ':siteId==='unsure'?'We can check the label. ':'This label names another place. '}${cardId==='photo'?'The photograph is labelled Quai des Grands-Augustins.':'The highest-mark event names the Austerlitz measuring scale.'} This modern schematic does not show flood extent or a route.`};}
function orderResult(order){if(!unique(order,eventIds))return null;const complete=order.length===3,correct=complete&&order.every((id,i)=>id===eventIds[i]);return {complete,correct,feedback:!complete?'You can keep an unfinished order. Compare the January, February and March dates when you want to add another card.':correct?'These cards run from 28 January to 9 February to 15 March. Their spaces show order, not equal lengths of time.':'Compare the printed dates: January comes before February, and February before March. You can move any card; nothing has been changed for you.'};}
export function archiveReplyFeedback(reply){
 if(!replyValid(reply))return null;
 const claim=reply.claim===null?{status:'unobserved',feedback:'No claim selected. You can leave a draft unfinished.'}:reply.claim==='return-later'?{status:'supported',feedback:'The chronology places the river’s return to its bed after its peak. It does not date every street drying.'}:reply.claim==='unsure'?{status:'uncertain',feedback:'Not sure is welcome. Compare the chronology’s peak and return dates.'}:{status:'limited',feedback:'The sources do not support all Paris being dry at the peak. The chronology places the river’s return later.'};
 const evidence=reply.evidence===null?{status:'unobserved',feedback:'No evidence selected. The chronology’s two date cards can help with the timing question.'}:['chronology','both'].includes(reply.evidence)?{status:'supported',feedback:reply.evidence==='both'?'The chronology supplies the peak and return dates. The photo adds a local view; it is not required proof of those dates.':'The chronology’s peak and return cards directly support the date sequence.'}:{status:'limited',feedback:reply.evidence==='photo'?'The photo shows a local view, but alone cannot establish the peak and return dates. Its production date is not automatically the scene’s capture time.':'Black-and-white tones do not establish an event date. Use the source labels and chronology.'};
 const limit=reply.limit===null?{status:'unobserved',feedback:'You can leave this blank or name something the packet cannot tell us.'}:{status:'supported',feedback:reply.limit==='depth'?'This picture has no measured street-depth scale.':reply.limit==='feelings'?'Neither supplied source records everybody’s feelings.':'Neither exact street depth nor everybody’s feelings can be established from these sources.'};
 return {claim,evidence,limit,originalText:'Original words are kept for a human reader. They are not automatically checked or graded.'};
}
function responseValid(task,r){
 if(task==='order')return keys(r,['order'])&&unique(r.order,eventIds);
 if(task==='reply')return replyValid(r);
 if(task.startsWith('map-'))return keys(r,['cardId','siteId'])&&r.cardId===task.slice(4)&&archiveMapCardById(r.cardId)!==null&&siteValid(r.siteId);
 return keys(r,['questionId','choice'])&&r.questionId===task&&questionResult(r.questionId,r.choice)!==null;
}
function taskSources(task){if(task==='reply')return sourceIds;if(task==='order')return ['chronology'];if(task.startsWith('map-'))return archiveMapCardById(task.slice(4))?.sourceIds??[];return archiveQuestionById(task)?.sourceIds??[];}
function resultFor(task,response){if(task==='order')return orderResult(response.order);if(task==='reply')return archiveReplyFeedback(response);if(task.startsWith('map-'))return mapResult(response.cardId,response.siteId);return questionResult(response.questionId,response.choice);}
function checkValid(c){return keys(c,['task','response','sourceIds','packId','sources','support','reading','practice','familiar','feedback'])&&TASK_IDS.includes(c.task)&&c.task!=='global'&&responseValid(c.task,c.response)&&equal(c.sourceIds,taskSources(c.task))&&c.packId===ARCHIVE_PACK.id&&equal(c.sources,sourceSnapshots(c.sourceIds))&&supportValid(c.support)&&READING.includes(c.reading)&&c.practice===true&&typeof c.familiar==='boolean'&&equal(c.feedback,resultFor(c.task,c.response));}
function keptValid(k){return k===null||keys(k,['packId','reply','sources','support','reading','familiar','checks','notice'])&&k.packId===ARCHIVE_PACK.id&&replyValid(k.reply)&&equal(k.sources,sourceSnapshots(sourceIds))&&supportsValid(k.support)&&READING.includes(k.reading)&&typeof k.familiar==='boolean'&&Array.isArray(k.checks)&&k.checks.length<=24&&k.checks.every(checkValid)&&k.notice===ARCHIVE_PACK.notice;}
function valid(r){return keys(r,['version','packId','page','task','source','detail','map','order','answers','reply','support','reading','sourcesExposed','revealedTasks','familiar','exposureUnknown','checks','kept'],['recovered','question'])&&(!Object.hasOwn(r,'question')||archiveQuestionById(r.question)!==null)&&(!['claims','source-choice','limits'].includes(r.task)||!Object.hasOwn(r,'question')||archiveQuestionById(r.question)?.task===r.task)&&r.version===1&&r.packId===ARCHIVE_PACK.id&&ARCHIVE_PAGES.includes(r.page)&&ARCHIVE_TASKS.includes(r.task)&&sourceIds.includes(r.source)&&ARCHIVE_DETAILS.includes(r.detail)&&mapValid(r.map)&&unique(r.order,eventIds)&&answersValid(r.answers)&&replyValid(r.reply)&&supportsValid(r.support)&&READING.includes(r.reading)&&unique(r.sourcesExposed,sourceIds)&&unique(r.revealedTasks,TASK_IDS.filter(t=>t!=='global'))&&typeof r.familiar==='boolean'&&typeof r.exposureUnknown==='boolean'&&Array.isArray(r.checks)&&r.checks.length<=24&&r.checks.every(checkValid)&&keptValid(r.kept);}
const fresh=()=>({version:1,packId:ARCHIVE_PACK.id,page:'parcel',task:'map',source:'photo',detail:'whole',map:{photo:null,gauge:null},order:[],answers:{},reply:{claim:null,evidence:null,limit:null,text:''},support:{},reading:'unobserved',sourcesExposed:[],revealedTasks:[],familiar:false,exposureUnknown:false,checks:[],kept:null});
// Selectors never create a response, expose a source or rewrite unavailable work.
export function travelersArchive(state){return state.travelersArchive===undefined?fresh():valid(state.travelersArchive)?state.travelersArchive:null;}
export function ensureTravelersArchive(state){if(state.travelersArchive===undefined)state.travelersArchive=fresh();return travelersArchive(state);}
export function recoverTravelersArchive(state){if(state.travelersArchive===undefined||travelersArchive(state))return false;const original=state.travelersArchive;state.travelersArchive={...fresh(),familiar:true,exposureUnknown:true,recovered:original};return true;}
function change(state,fn){const r=travelersArchive(state);if(!r)return false;const next=clone(r),value=fn(next);if(value===false||!valid(next))return false;state.travelersArchive=next;return value??true;}
const mergedSupport=(r,task)=>({...r.support.global,...r.support[task]});
function record(r,task,response){const result=resultFor(task,response),ids=taskSources(task);if(!result)return false;const c={task,response:clone(response),sourceIds:clone(ids),packId:ARCHIVE_PACK.id,sources:sourceSnapshots(ids),support:mergedSupport(r,task),reading:r.reading,practice:true,familiar:r.familiar||r.exposureUnknown||r.revealedTasks.includes(task),feedback:clone(result)};r.checks.push(c);r.checks=r.checks.slice(-24);if(!r.revealedTasks.includes(task))r.revealedTasks.push(task);return clone(result);}
export function setArchivePage(state,page){return ARCHIVE_PAGES.includes(page)?change(state,r=>{r.page=page;}):false;}
export function setArchiveTask(state,task){return ARCHIVE_TASKS.includes(task)?change(state,r=>{r.task=task;if(['claims','source-choice','limits'].includes(task)&&archiveQuestionById(r.question)?.task!==task)r.question=ARCHIVE_QUESTIONS.find(q=>q.task===task).id;}):false;}
export function setArchiveQuestion(state,id){const q=archiveQuestionById(id);return q?change(state,r=>{r.question=id;r.task=q.task;}):false;}
export function setArchiveSource(state,id){return sourceIds.includes(id)?change(state,r=>{r.source=id;}):false;}
export function setArchiveDetail(state,id){return ARCHIVE_DETAILS.includes(id)?change(state,r=>{r.detail=id;}):false;}
export function setArchiveMap(state,cardId,siteId){return archiveMapCardById(cardId)&&siteValid(siteId)?change(state,r=>{r.map[cardId]=siteId;}):false;}
export function checkArchiveMap(state,cardId){return archiveMapCardById(cardId)?change(state,r=>record(r,`map-${cardId}`,{cardId,siteId:r.map[cardId]})):false;}
export function setArchiveOrder(state,order){return unique(order,eventIds)?change(state,r=>{r.order=[...order];}):false;}
export function placeArchiveEvent(state,id,index){if(!archiveEventById(id)||!Number.isInteger(index)||index<0||index>2)return false;return change(state,r=>{const order=r.order.filter(x=>x!==id);if(index>order.length)return false;order.splice(index,0,id);r.order=order;});}
export function moveArchiveEvent(state,id,delta){if(!archiveEventById(id)||![-1,1].includes(delta))return false;return change(state,r=>{const i=r.order.indexOf(id),j=i+delta;if(i<0||j<0||j>=r.order.length)return false;[r.order[i],r.order[j]]=[r.order[j],r.order[i]];});}
export function checkArchiveOrder(state){return change(state,r=>record(r,'order',{order:r.order}));}
export function answerArchiveQuestion(state,id,choice){const result=questionResult(id,choice);if(!result)return false;return change(state,r=>{r.answers[id]=choice;return record(r,id,{questionId:id,choice});});}
export function setArchiveReplyChoice(state,field,choice){return archiveReplyFieldById(field)&&choiceValid(field,choice)?change(state,r=>{r.reply[field]=choice;}):false;}
export function setArchiveReplyText(state,text){const count=typeof text==='string'?Array.from(text).length:null;if(count===null)return {ok:false,count:null,limit:ARCHIVE_TEXT_LIMIT,error:'Text must be a string.'};if(count>ARCHIVE_TEXT_LIMIT)return {ok:false,count,limit:ARCHIVE_TEXT_LIMIT,error:'Your words are longer than this local draft can hold. Nothing was shortened or saved; please use at most 2,000 characters.'};const ok=change(state,r=>{r.reply.text=text;});return {ok:ok!==false,count,limit:ARCHIVE_TEXT_LIMIT,...(ok===false?{error:'This saved archive is unavailable. Your existing work has not been replaced.'}:{})};}
export function checkArchiveReply(state){return change(state,r=>record(r,'reply',r.reply));}
export function keepArchiveReply(state){return change(state,r=>{r.kept={packId:ARCHIVE_PACK.id,reply:clone(r.reply),sources:sourceSnapshots(sourceIds),support:clone(r.support),reading:r.reading,familiar:r.familiar||r.exposureUnknown||r.revealedTasks.includes('reply'),checks:clone(r.checks),notice:ARCHIVE_PACK.notice};return clone(r.kept);});}
export function useArchiveSupport(state,kind,task='global'){if(!SUPPORT.includes(kind)||!TASK_IDS.includes(task))return false;return change(state,r=>{r.support[task]??={};r.support[task][kind]=true;if(['help','example'].includes(kind)&&task!=='global'&&!r.revealedTasks.includes(task))r.revealedTasks.push(task);});}
export function noteArchiveSources(state,ids){if(!unique(ids,sourceIds))return false;return change(state,r=>{for(const id of ids)if(!r.sourcesExposed.includes(id))r.sourcesExposed.push(id);});}
export function setArchiveReading(state,mode){return READING.includes(mode)?change(state,r=>{r.reading=mode;}):false;}
export function revisitArchive(state){return change(state,r=>{r.familiar=true;});}
